def transform(input_grid):
    from copy import deepcopy
    rows, cols = len(input_grid), len(input_grid[0])
    result = deepcopy(input_grid)

    # Horizontal
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 1:
                left_2 = None
                for lc in range(c-1, -1, -1):
                    if input_grid[r][lc] == 2:
                        left_2 = lc
                        break
                right_2 = None
                for rc in range(c+1, cols):
                    if input_grid[r][rc] == 2:
                        right_2 = rc
                        break
                if left_2 is not None and right_2 is not None:
                    result[r][c] = 3

    # Vertical  
    for c in range(cols):
        for r in range(rows):
            if input_grid[r][c] == 1 and result[r][c] != 3:
                above_2 = None
                for ar in range(r-1, -1, -1):
                    if input_grid[ar][c] == 2:
                        above_2 = ar
                        break
                below_2 = None
                for br in range(r+1, rows):
                    if input_grid[br][c] == 2:
                        below_2 = br
                        break
                if above_2 is not None and below_2 is not None:
                    result[r][c] = 3

